workflow-item.script:
if (!baseUrl || !project || !token) {
    throw new Error("VCFA URL, CCI project namespace and access token are required.");
}
var endpoint = "/cci/kubernetes/apis/topology.cci.vmware.com/v1alpha1/namespaces/" +
    encodeURIComponent(project) + "/regionbindings";
var restHost = RESTHostManager.createHost("DynamicRequest");
var transientHost = RESTHostManager.createTransientHostFrom(restHost);
transientHost.url = baseUrl;
var request = transientHost.createRequest("GET", endpoint, null);
request.setHeader("Authorization", "Bearer " + token);
request.setHeader("Accept", "application/json");
var response = request.execute();
System.log("Region bindings request returned HTTP " + response.statusCode);
if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error("Cannot retrieve region bindings: HTTP " + response.statusCode);
}
var result = JSON.parse(response.contentAsString);
var items = result.items || [];
System.log("Region bindings returned: " + items.length);
for (var i = 0; i < items.length; i++) {
    System.log("Region binding: " + items[i].metadata.name);
}
